const event = $input.first().json || {};
const execution = event.execution || {};
const workflow = event.workflow || {};
const raw = String(execution.error?.message || execution.error || event.message || 'Unhandled workflow failure');
const sanitized = raw
  .replace(/(authorization|api[-_ ]?key|token|secret|password|cookie)\s*[:=]\s*[^,;\s]+/gi, '$1=[REDACTED]')
  .replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/gi, 'Bearer [REDACTED]')
  .replace(/[\r\n\t]+/g, ' ')
  .slice(0, 1000);
const workflowKey = String(workflow.name || workflow.id || 'unknown-workflow');
const executionId = String(execution.id || '');
const now = new Date().toISOString();
return [{ json: {
  run_id: executionId ? workflowKey + ':' + executionId : 'error:' + Date.now(),
  workflow_key: workflowKey,
  execution_id: executionId,
  trigger_type: 'error-workflow',
  status: 'failed',
  started_at: execution.startedAt || now,
  finished_at: now,
  duration_ms: 0,
  idempotency_key: '',
  error_class: String(execution.error?.name || 'UnhandledWorkflowError').slice(0, 120),
  error_summary: sanitized,
  payload_excerpt: ''
} }];

